fcIfRxDataFieldSize = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 289, 1, 1, 2, 1, 28), FcRxDataFieldSize()).setUnits('bytes').setMaxAccess("readwrite")
if mibBuilder.loadTexts: fcIfRxDataFieldSize.setStatus('current')
